const books = input.books ?? [];

if (input.operation === "delete") {
  console.log(JSON.stringify({
    http: { status: 204, headers: {}, body: null },
    database: { books: books.filter((book) => book.id !== input.bookId), deleted: [input.bookId] },
    failures: []
  }));
